var i=`authentication-vs-authorization`;var s=65;var n={en:[{id:`T065-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Authentication vs Authorization`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`REST is an architectural style for networked systems emphasizing resources, uniform interfaces, stateless interactions, layered components and representations.`},{id:`B`,text:`Authentication establishes who or what is making a request; authorization determines what that principal may do.`},{id:`C`,text:`Pagination bounds response size and enables scalable navigation; filtering selects records according to an explicit query contract.`},{id:`D`,text:`Webhooks deliver events via outbound HTTP calls; message queues broker asynchronous delivery between producers and consumers.`}]},{id:`T065-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Authentication vs Authorization`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Model resource identity with URIs, use HTTP methods according to semantics, return appropriate status codes, support caching when correct, and expose links when hypermedia is part of the contract.`},{id:`B`,text:`Prefer additive contracts, optional fields with sensible defaults, tolerant readers within documented bounds, and explicit deprecation policies.`},{id:`C`,text:`Check token/session validity, then evaluate permissions against action, resource and context.`},{id:`D`,text:`Offset pagination is simple but can degrade at large offsets and shift under concurrent inserts.`}]},{id:`T065-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`The backend still authorizes each booking.`},{id:`B`,text:`The new server must interpret it predictably while adding optional guest preferences for newer clients.`},{id:`C`,text:`Even a valid staff JWT must not grant access to another tenant's reservation by changing an ID.`},{id:`D`,text:`The receiver verifies authenticity, stores the event ID, acknowledges quickly and processes the state change asynchronously once.`}]},{id:`T065-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Authentication vs Authorization`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Silent reinterpretation is worse than a clear rejection; changing default units, enum meanings or sort order can break clients without changing schemas.`},{id:`B`,text:`Client-side route guards improve UX but are not security controls.`},{id:`C`,text:`IP-only limits punish users behind shared NAT and may miss distributed attackers.`},{id:`D`,text:`Do not equate REST with CRUD-only design.`}]},{id:`T065-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Both are necessary, and being logged in never implies unrestricted access.`}]}]},{id:`T065-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A valid login token grants permission to read every tenant's data.`}]}]},{id:`T065-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Missing object-level checks create IDOR/BOLA risks; permissions may change after token issuance.`}]}]},{id:`T065-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Authentication vs Authorization`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Authorization checks are only necessary on the login route.`},{id:`B`,text:`Check token/session validity, then evaluate permissions against action, resource and context.`},{id:`C`,text:`REST requires JSON responses and a separate endpoint for each database table.`},{id:`D`,text:`Authentication establishes who or what is making a request; authorization determines what that principal may do.`}]},{id:`T065-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Authentication vs Authorization`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Cursor pagination guarantees consistent ordering even when the sort key is not stable.`},{id:`B`,text:`Even a valid staff JWT must not grant access to another tenant's reservation by changing an ID.`},{id:`C`,text:`A valid login token grants permission to read every tenant's data.`},{id:`D`,text:`Missing object-level checks create IDOR/BOLA risks; permissions may change after token issuance.`}]},{id:`T065-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to design a distributed token-bucket limiter with tenant fairness, burst behavior, 429 responses and metrics for legitimate versus abusive traffic.`},{id:`B`,text:`Ask an agent to design tenant-aware authorization for bookings, including service accounts and revoked permissions. Require tests for horizontal and vertical privilege escalation.`},{id:`C`,text:`Have an agent review a booking API's resources, methods, error responses, caching and concurrency headers. Ask for example requests and contract tests.`},{id:`D`,text:`Ask an agent to evolve a booking contract with old-client fixtures, property-based validation and a deprecation plan informed by client version metrics.`}]},{id:`T065-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Where is the authoritative point that decides whether this user may access this record?`}]}]},{id:`T065-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Authentication vs Authorization`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T065-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0},{t:` — propose three checks for `},{t:`Authentication vs Authorization`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T065-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T065-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Authentication vs Authorization`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A hotel employee may view bookings for assigned properties but not other hotels.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T065-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Автентифікація та авторизація`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`REST — архітектурний стиль мережевих систем, що наголошує на ресурсах, уніфікованому інтерфейсі, відсутності стану сесії на сервері, шарах і представленнях.`},{id:`B`,text:`Автентифікація встановлює особу або сервіс, що робить запит; авторизація визначає дозволені дії.`},{id:`C`,text:`Пагінація обмежує розмір відповіді й забезпечує навігацію; фільтрація відбирає записи за явним контрактом запиту.`},{id:`D`,text:`Webhook передає події вихідним HTTP-запитом; черга повідомлень доставляє асинхронні задачі між виробником і споживачем.`}]},{id:`T065-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Автентифікація та авторизація`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Моделюйте ідентичність ресурсу через URI, дотримуйтеся семантики HTTP-методів, повертайте належні статуси, застосовуйте кешування, а посилання між ресурсами — коли це частина контракту.`},{id:`B`,text:`Віддавайте перевагу додаванню полів, необов’язковим значенням із розумними defaults, читачам, які терплять документовану варіативність, і явним правилам deprecation.`},{id:`C`,text:`Перевіряйте токен або сесію, потім оцінюйте дозвіл з огляду на дію, ресурс і контекст.`},{id:`D`,text:`Offset-пагінація проста, але повільніша на великих зміщеннях і зміщується при нових записах.`}]},{id:`T065-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Бекенд усе одно перевіряє право на бронювання.`},{id:`B`,text:`Новий сервер має передбачувано його тлумачити й приймати нові необов’язкові побажання гостей.`},{id:`C`,text:`Навіть чинний JWT співробітника не дозволяє отримати чужу бронь шляхом заміни ID.`},{id:`D`,text:`Приймач перевіряє автентичність, зберігає ID, швидко підтверджує прийом і асинхронно обробляє зміну стану.`}]},{id:`T065-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Автентифікація та авторизація`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Тиха зміна значення гірша за явну помилку; інші одиниці, значення enum чи порядок сортування можуть ламати клієнти без зміни схеми.`},{id:`B`,text:`Клієнтські route guards покращують UX, але не є захистом.`},{id:`C`,text:`Ліміт лише за IP карає користувачів за спільним NAT і пропускає розподілені атаки.`},{id:`D`,text:`Не зводьте REST до CRUD.`}]},{id:`T065-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Обидві потрібні, а сам факт входу не означає повний доступ.`}]}]},{id:`T065-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Чинний токен входу дозволяє читати дані будь-якого орендаря.`}]}]},{id:`T065-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Відсутність перевірки конкретного об’єкта створює IDOR/BOLA; права можуть змінитися після видачі токена.`}]}]},{id:`T065-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Автентифікація та авторизація`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Перевіряти авторизацію потрібно лише на маршруті входу.`},{id:`B`,text:`Перевіряйте токен або сесію, потім оцінюйте дозвіл з огляду на дію, ресурс і контекст.`},{id:`C`,text:`REST вимагає JSON-відповідей і окремого endpoint для кожної таблиці БД.`},{id:`D`,text:`Автентифікація встановлює особу або сервіс, що робить запит; авторизація визначає дозволені дії.`}]},{id:`T065-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Автентифікація та авторизація`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Cursor-пагінація гарантує порядок навіть із нестабільним ключем сортування.`},{id:`B`,text:`Навіть чинний JWT співробітника не дозволяє отримати чужу бронь шляхом заміни ID.`},{id:`C`,text:`Чинний токен входу дозволяє читати дані будь-якого орендаря.`},{id:`D`,text:`Відсутність перевірки конкретного об’єкта створює IDOR/BOLA; права можуть змінитися після видачі токена.`}]},{id:`T065-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента спроєктувати розподілений token bucket із справедливістю між tenant, підтримкою burst, 429 і метриками легального та зловмисного трафіку.`},{id:`B`,text:`Попросіть агента спроєктувати tenant-aware авторизацію бронювань, включно із сервісними акаунтами та відкликаними правами. Вимагайте тести горизонтального й вертикального підвищення привілеїв.`},{id:`C`,text:`Попросіть агента перевірити ресурси API бронювань, методи, помилки, кешування та заголовки конкурентності. Вимагайте приклади запитів і контрактні тести.`},{id:`D`,text:`Попросіть агента розвинути контракт бронювання з фікстурами старих клієнтів, перевіркою властивостей і планом deprecation за метриками версій.`}]},{id:`T065-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Де знаходиться авторитетна точка рішення, чи може користувач переглядати конкретний запис?`}]}]},{id:`T065-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Автентифікація та авторизація`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T065-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Автентифікація та авторизація`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T065-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T065-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Автентифікація та авторизація`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Працівник готелю може бачити бронювання лише закріплених об’єктів.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:65,questions:n};export{o as default,n as questions,i as slug,s as topicId};